/// <summary>
/// MPJ_24248 Pricing Data Extract
/// Price Change Tracking instance factory
/// </summary>
final static class METPriceChangeTrackFactory
{
}

Method.Source:
    /// <summary>
    /// MPJ_24248 Pricing Data Extract
    /// Create Price Change Tracking instance
    /// </summary>
    /// <param name = "_priceChangeType">Price change type</param>
    /// <returns>Instance of Price Change Tracking</returns>
    public static METPriceChangeTrack newFromPriceChangeType(METPriceChangeType _priceChangeType)
    {
        SysPluginMetadataCollection metadataCollection = new SysPluginMetadataCollection();

        metadataCollection.SetManagedValue( enumStr(METPriceChangeType),
                                            enum2Symbol(enumNum(METPriceChangeType),
                                            enum2int(_priceChangeType)));

        METPriceChangeTrack instance = SysPluginFactory::Instance(identifierStr(Dynamics.AX.Application),
                                                                                classStr(METPriceChangeTrack),
                                                                                metadataCollection);
        
        if (!instance)
        {
            throw Error(strFmt("@SYS19306",funcName()));
        }
    
        return instance;
    }
